import{KEY,STAGES,topic,safeURL,validateState,filterRows,csvCell,outreach,cleanWork}from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={version:1,work:{},custom:[]},base=[],visible=[];
const tell=s=>$('#notice').textContent=s;
try{const s=localStorage.getItem(KEY);if(s)state=validateState(JSON.parse(s));}catch{tell('No s’ha pogut llegir el seguiment desat. La base es carregarà sense modificar la còpia anterior.');}
const all=()=>[...base,...state.custom];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{tell('No s’ha pogut desar al navegador. Exporta la còpia JSON abans de tancar.');return false;}}
function link(url,label){const u=safeURL(url);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'Sense enllaç verificat';}
function draw(){const rows=all(),filters=Object.fromEntries(['q','region','tag','contact','stage','mode'].map(k=>[k,$('#'+k).value]));visible=filterRows(rows,filters,state.work);$('#units').textContent=rows.length;$('#countries').textContent=new Set(rows.map(r=>r.country)).size;$('#working').textContent=rows.filter(r=>['Preparant proposta','Contactat','En conversa','Proposta enviada','Confirmat'].includes(state.work[r.id]?.stage)).length;$('#count').textContent=`${visible.length} de ${rows.length} unitats`;
$('#results').innerHTML=visible.length?visible.map(r=>{const w=state.work[r.id]||cleanWork();return`<article class="uni"><p class="meta">${esc(r.city)} · ${esc(r.country)}</p><h3>${esc(r.name)}</h3><p class="meta">${esc(r.kind)}</p><p><b>${esc(r.unit)}</b></p><div class="pills">${r.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div><div class="scores"><span>Encaix <b>${r.fit}/5</b></span><span>Projecció <b>${r.reach}/5</b></span></div><p>${esc(r.angle)}</p><p class="meta"><b>Porta suggerida:</b> ${esc(r.who||'Per localitzar')}</p><p><span class="pill ${r.contactLevel==='Pendent'?'contact-pending':''}">Contacte · ${esc(r.contactLevel)}</span></p><p class="state">${esc(w.stage)}${w.date?' · proper pas '+esc(w.date):''}</p><button class="open" data-id="${esc(r.id)}">Fitxa, proposta i seguiment ↗</button></article>`;}).join(''):'<p class="empty">No hi ha centres amb aquests filtres. Canvia la cerca o afegeix un centre.</p>';}
function detail(id){const r=all().find(r=>r.id===id);if(!r)return;const w=state.work[id]||cleanWork(),t=topic(r);$('#detail-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${esc(r.region)} · ${esc(r.country)}</div><h2>${esc(r.name)}</h2><p>${esc(r.unit)}</p></div><button data-close>Tanca ×</button></div><div class="detail-grid"><div><section><h3>Encaix i proposta editorial</h3><p><b>Angle específic:</b> ${esc(r.angle)}</p><p><b>Format inicial:</b> ${esc(t.format)}. Públic suggerit: estudiants i professorat del programa o equip indicat.</p><p><b>${esc(t.title)}</b></p><p>${esc(t.workshop)}</p><p><b>Alternativa:</b> ponència de 30–45 min en jornada pública + reunió amb professorat. Confirmar que hi ha un acte i pressupost abans de preparar-la.</p><p><b>Objectiu de projecció:</b> acordar difusió pública, un contacte docent estable i una possible segona col·laboració. Ni l’audiència ni la contractació estan garantides.</p><p><b>Ruta suggerida:</b> ${esc(r.route)}</p><p class="small">Encaix ${r.fit}/5: afinitat temàtica estimada. Projecció ${r.reach}/5: potencial editorial d’intercanvi internacional. Ordenació internacional: mateix pes per a tots dos; ordenació per encaix: pes 5:1. No són puntuacions facilitades pel centre.</p></section><section><h3>Amb qui contactar</h3><p>${esc(r.who)}</p><p><b>Canal:</b> ${esc(r.contactLevel)}${r.email?' · '+esc(r.email):''}</p><p>${link(r.contactUrl,r.contactLevel==='Pendent'?'Pàgina per localitzar el contacte':'Canal institucional / directori')}</p><p>${link(r.source,'Font del programa o equip')}</p><p class="small">${r.reviewed?'Consulta documental: '+esc(r.reviewed)+'.':'Fitxa afegida per l’usuari: pendent de verificació.'} El canal pot ser general. Cal confirmar que la persona gestiona col·laboracions externes i que el programa continua vigent. No hi ha invitació ni disponibilitat confirmades.</p></section></div><div><section><h3>Seguiment del contacte</h3><form id="work-form"><label>Estat<select name="stage">${STAGES.map(s=>`<option${s===w.stage?' selected':''}>${s}</option>`).join('')}</select></label><label>Responsable intern<input name="owner" value="${esc(w.owner)}"></label><label>Contacte real confirmat per vosaltres<input name="contactName" value="${esc(w.contactName)}"></label><label>Últim contacte<input type="date" name="last" value="${esc(w.last)}"></label><label>Següent acció<input name="next" value="${esc(w.next)}" placeholder="Enviar dossier d’una pàgina…"></label><label>Data interna del següent pas<input type="date" name="date" value="${esc(w.date)}"></label><div class="budget"><label>Honoraris previstos (€)<input type="number" min="0" step="0.01" name="honorarium" value="${esc(w.honorarium)}"></label><label>Viatge i altres costos (€)<input type="number" min="0" step="0.01" name="travel" value="${esc(w.travel)}"></label></div><label>Notes, pressupost i resposta<textarea name="notes">${esc(w.notes)}</textarea></label><button type="submit" class="primary">Desa el seguiment</button><p id="save-status" role="status"></p></form></section></div></div><section><h3>Esborrany per adaptar · no s’envia</h3><label>Llengua de l’esborrany<select id="draft-language"><option value="en">Anglès</option><option value="ca">Català</option></select></label><p class="small">Afegeix nom, signatura i una connexió concreta amb el programa. La disponibilitat i la llengua de les persones ponents s’han de confirmar.</p><label>Text editable<textarea id="draft"></textarea></label><button id="copy">Copia el text</button> <button id="download-draft">Descarrega el text</button><p id="copy-status" role="status"></p></section>`;
$('#draft').value=outreach(r);$('#draft-language').onchange=()=>{$('#draft').value=outreach(r,$('#draft-language').value);};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#draft').value);$('#copy-status').textContent='Text copiat.';}catch{$('#draft').select();$('#copy-status').textContent='Selecciona i copia el text amb el teclat, o descarrega’l.';}};$('#download-draft').onclick=()=>download(`proposta-${id}.txt`,$('#draft').value,'text/plain');$('#work-form').onsubmit=e=>{e.preventDefault();state.work[id]=cleanWork(Object.fromEntries(new FormData(e.target)));const ok=save();draw();$('#save-status').textContent=ok?'Seguiment desat en aquest navegador.':'No s’ha pogut desar. Exporta una còpia JSON.';};$('#detail').showModal();}
function download(name,data,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
document.addEventListener('click',e=>{const open=e.target.closest('[data-id]');if(open)detail(open.dataset.id);const close=e.target.closest('[data-close]');if(close)close.closest('dialog').close();});
for(const k of ['q','region','tag','contact','stage','mode'])$('#'+k).addEventListener(k==='q'?'input':'change',draw);
$('#backup').onclick=()=>download('top-manta-universitats.json',JSON.stringify(state,null,2),'application/json');
$('#csv').onclick=()=>{const header=['Institució','País','Ciutat','Regió','Tipus','Programa/equip','Àmbits','Encaix /5','Projecció /5','Contacte suggerit','Email públic','Canal','Font acadèmica','Font contacte','Angle proposat','Estat','Responsable','Contacte confirmat','Últim contacte','Següent pas','Data interna','Honoraris previstos EUR','Viatge i altres EUR','Notes'];const data=visible.map(r=>{const w=state.work[r.id]||cleanWork();return[r.name,r.country,r.city,r.region,r.kind,r.unit,r.tags.join(' / '),r.fit,r.reach,r.who,r.email,r.contactLevel,r.source,r.contactUrl,r.angle,w.stage,w.owner,w.contactName,w.last,w.next,w.date,w.honorarium,w.travel,w.notes];});download('universitats-top-manta.csv','\ufeff'+[header,...data].map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('La còpia supera els 5 MB.');const v=validateState(JSON.parse(await file.text()));const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download('universitats-abans-importacio.json',await blob.text(),'application/json');state=v;save();populate();draw();tell('Còpia importada. S’ha descarregat una còpia del seguiment anterior.');}catch(err){tell('No s’ha importat: '+err.message);}e.target.value='';};
$('#add').onclick=()=>$('#new').showModal();$('#new-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));state.custom.push({id:'custom-'+crypto.randomUUID(),name:f.name.trim(),country:f.country.trim(),city:f.city,region:f.region,kind:'Tipus pendent de verificar',unit:f.unit,tags:[f.tag],source:safeURL(f.source),contactUrl:safeURL(f.source),who:f.who,email:'',contactLevel:'Pendent',fit:3,reach:3,angle:topic({tags:[f.tag]}).title,route:'Per definir',reviewed:''});save();populate();draw();$('#new').close();e.target.reset();tell('Centre afegit com a fitxa personal pendent de verificar.');};
function populate(){for(const[k,values]of [['region',[...new Set(all().map(r=>r.region))]],['tag',[...new Set(all().flatMap(r=>r.tags))]],['stage',STAGES]]){const el=$('#'+k),current=el.value;while(el.options.length>1)el.remove(1);values.forEach(v=>el.add(new Option(v,v)));el.value=current;}}
try{const res=await fetch('data.json');if(!res.ok)throw Error('Resposta '+res.status);base=(await res.json()).rows;populate();draw();}catch{tell('No s’ha pogut carregar la base universitària. Torna a carregar la pàgina.');draw();}
